// The app owns scroll positions on its routed screens, including learner-switch reloads.
if('scrollRestoration' in history)history.scrollRestoration='manual';
const root=document.querySelector('#app'),PKEY='fixiverse-pattern-v1';let grove=newPattern(),storage=!window.fixiverseStorage.memoryOnly;try{window.fixiverseStorage.setItem('fixiverse-storage-check','1');window.fixiverseStorage.removeItem('fixiverse-storage-check');}catch{storage=false;}
const read=key=>{try{return JSON.parse(window.fixiverseStorage.getItem(key)||'null');}catch{return null;}};
const saved=read(PKEY);if(saved?.version===1&&['build','repair','check','complete'].includes(saved.phase)&&Array.isArray(saved.block)&&saved.block.every(t=>TOKENS.includes(t))&&Array.isArray(saved.answers)&&Number.isInteger(saved.index)&&saved.index>=0&&saved.index<3)grove=saved;if(grove.phase==='check'&&grove.answers.length===grove.index)grove.tested=false;
const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sun:'☀',leaf:'❧',star:'★',moon:'☾'};
const tile=(t,outline=false)=>`<span class="grove-tile ${t} ${outline?'loop-tile':''}" role="img" aria-label="${t}">${icons[t]}</span>`;
const control=(text,action,value='',disabled=false)=>`<button class="btn" data-hub="${action}" data-value="${value}" ${disabled?'disabled':''}>${text}</button>`;
const hubClass=()=>{const p=read("fixiverse-access-v1")||{};return `hub ${p.large?"large":""} ${p.motion?"reduced":""}`;};
const top=()=>`<header><div class="brand"><span class="brand-icon" aria-hidden="true"><i></i><i></i><i></i><i></i></span>fixiverse</div><div class="header-actions">${control('Tutor workspace','tutor')}${control('⌂ My workshop','home')}${control('◖ Read aloud','voice')}${control('Aa Text size','text-size')}</div></header>`;
function heading(text){return`<h1 id="screen-title" tabindex="-1">${text}</h1>`;}
function focus(){document.querySelector('#screen-title')?.focus({preventScroll:true});if(!window.fixiverseTour?.scrolling())window.scrollTo(0,0);}
function fractionStatus(){const s=read('fixiverse-foundry-v1');return s?.phase==='complete'?(s.repairPassed?'Repair installed':'Practice saved'):s&&s.phase!=='welcome'?'Investigation in progress':'Ready to explore';}
function home(){
if(['#tutor','#session','#teach-fraction','#teach-pattern','#lab-fraction','#lab-pattern'].includes(location.hash))history.replaceState(null,'',location.pathname+location.search);
const f=read('fixiverse-foundry-v1'),g=read(PKEY);
const repaired=Number(!!f?.repairPassed||(read('fixiverse-investigations-v1')||[]).some(r=>r.ruleRepaired))+Number(!!g?.repaired||!!read('fixiverse-grove-repaired-v1'));
window.fixiverseBookshelf.show({alias:window.fixiverseProfiles.list().find(p=>p.id===window.fixiverseProfiles.active()).alias,repaired,storage,fractionStatus:fractionStatus(),patternStatus:g?.phase==='complete'?'Investigation saved':g?'Investigation in progress':'Ready to explore'});
}
function patternScreen(){const active=document.activeElement;const action=active?.dataset?.hub,value=active?.dataset?.value,slot=active?.dataset?.slot;document.title='Fixiverse · Pattern Grove';const s=grove,c=PATTERN_CHECKS[s.index],block=s.phase==='check'?c.block:s.block,length=s.phase==='check'?c.length:4;const sequence=Array.from({length},(_,i)=>tile(block[i%block.length],i<block.length)).join('');const choices=TOKENS.map(t=>`<button class="tile-choice ${s.choice===t?'picked':''}" data-hub="choose" data-value="${t}" ${s.phase==='check'&&s.tested?'disabled':''} aria-pressed="${s.choice===t}">${tile(t).replace('role="img" aria-label="'+t+'"','aria-hidden="true"')}<span>${t}</span></button>`).join('');root.className=hubClass()+' storybook-mission pattern-chapter';root.innerHTML=`${top()}<main id="main" class="grove-shell"><div class="eyebrow">MISSION 02 / PATTERN GROVE</div>${heading(s.phase==='build'?'What comes next?':s.phase==='repair'?'Help the loop find its way.':s.phase==='check'?'A new pattern. Your idea.':'Look what you helped grow.')}<p class="lede">${s.phase==='build'?'Build a repeating pattern and help Pip follow it.':s.phase==='repair'?'Look at your loop. Pick a rule. Then try your repair.':s.phase==='check'?`Fresh pattern ${s.index+1} of 3. The outlined tiles repeat again and again.`:'You investigated a pattern and installed a new rule.'}</p>${s.phase!=='complete'?control('Need a hint?','hint'):''}<div class="grove-layout"><section class="panel"><div class="panel-body">${s.phase==='complete'?`<div class="grove-celebrate" aria-hidden="true">${tile('sun')}${tile('leaf')}${tile('star')}</div><h2>The Grove has its rhythm back.</h2><p>You repaired “keep copying the last tile” into “follow the repeating loop.”</p><p><b>${s.answers.filter(a=>a.correct).length} of ${s.answers.length}</b> fresh comparisons correct. Hints used: ${s.hints}.</p><p>This is a record of this visit. You can keep exploring with your tutor.</p><div class="btn-row">${control('Back to my workshop','home')}<button class="btn" data-growth="practice" data-mission="pattern">A little practice for me ↗</button>${control('Try another investigation','new-pattern')}</div>`:`<div class="grove-loop"><span class="eyebrow">THE REPEATING UNIT</span><div>${block.map(t=>tile(t,true)).join('')}</div></div>${s.phase==='build'?`<div class="loop-builder">${[0,1].map(i=>`<label>Tile ${i+1}<select data-slot="${i}" aria-label="Loop tile ${i+1}">${TOKENS.map(t=>`<option value="${t}" ${s.block[i]===t?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}</div>`:''}<p class="reason-label">Read from left to right. Repeat the ${block.length} outlined tiles.</p><div class="pattern-path">${sequence}<span class="grove-tile mystery" role="img" aria-label="Missing next tile">?</span></div>${s.phase==='repair'?`<div class="reason-options">${[['last','Keep copying the last tile'],['loop','Follow the whole loop, then start it again'],['sun','Always put a sun next']].map(([id,text])=>`<button class="rule-option ${s.candidate===id?'selected':''}" data-hub="rule" data-value="${id}" aria-pressed="${s.candidate===id}">${text}</button>`).join('')}</div><div class="btn-row">${control('Try my repair','patch','',!s.candidate)}${s.repaired?control('Try fresh patterns →','begin'):''}</div>`:`<p>What comes next?</p><div class="tile-choices">${choices}</div><div class="btn-row">${s.phase==='build'?control('Compare with Pip','test','',!s.choice):s.tested?control(s.index===2?'Keep my discovery →':'Next pattern →','next'):control('Check my tile','check','',!s.choice)}</div>${s.phase==='build'&&s.tested?`<div class="pip-comparison"><span>Pip’s old rule picks ${tile(patternPrediction('last',s.block,4))}</span><span>Your idea ${tile(s.choice)}</span></div>${s.choice===nextToken(s.block,4)&&s.choice!==patternPrediction('last',s.block,4)?control('Save clue and repair →','save'):s.block[0]===s.block[1]?'<p>Matching tiles agree with Pip here. Try two different tiles to expose the mix-up.</p>':''}`:''}`}${s.feedback?`<div class="result" role="status">${escape(s.feedback)}</div>`:''}`}</div></section><aside><section class="grove-companion"><div class="eyebrow">PIP’S GARDEN NOTE</div><div class="robot" aria-hidden="true"><div class="robot-screen"><i class="eye"></i><i class="eye"></i></div><div class="robot-mouth"></div></div><h3>${s.repaired?'A new way to grow.':'One good clue can help.'}</h3><p>${s.repaired?'I follow the small loop from start to finish. Then I start it again.':'My mixed-up rule keeps copying the very last tile. Does the loop agree?'}</p>${s.phase!=='complete'?control('A little hint, please','hint'):''}<p class="hint-text">The tile shapes and names match. You don’t have to use color to solve this.</p></section></aside></div></main>`;window.fixiverseMissionUI(root,{phase:'pattern-'+s.phase,steps:['Explore','Repair','Check','Keep it'],current:Math.max(0,['build','repair','check','complete'].indexOf(s.phase)),instruction:s.phase==='build'?(s.tested?(s.choice!==nextToken(s.block,4)?'Follow the outlined tiles from the start. Choose again, then select Compare with Pip.':s.choice!==patternPrediction('last',s.block,4)?'Your tile fits the pattern, and Pip’s does not. Select Save clue and repair.':'Pip agrees with this pattern. Choose two different tiles and try again.'):s.choice?'Your tile is selected. Select Compare with Pip.':'You can change the two tiles. Follow the pattern, then choose the tile that belongs in the question mark.'):s.phase==='repair'?(s.repaired?'Your repair fits the pattern. Select Try fresh patterns.':s.candidate?'Select Try my repair to test this rule.':'Choose a rule that explains how the outlined tiles repeat.'):s.phase==='check'?(s.tested?'Read the result, then continue to the next pattern.':'Choose the missing tile. Then select Check my tile.'):'Your discovery is saved. Return to the bookshelf or keep practicing.'});if(action&&["choose","rule","hint","test","patch","check"].includes(action)){document.querySelector(`[data-hub="${action}"][data-value="${value||''}"]`)?.focus({preventScroll:true});}else if(slot!==undefined){document.querySelector(`[data-slot="${slot}"]`)?.focus({preventScroll:true});}else focus();if(["test","check"].includes(action)&&!document.querySelector(`[data-hub="${action}"]`)){const result=root.querySelector(".result");if(result){result.tabIndex=-1;result.focus({preventScroll:true});}}}
function persist(){if(window.fixiverseTour?.active())return;try{if(!grove.id)grove.id=crypto.randomUUID();if(grove.phase==='complete'){const visits=read('fixiverse-pattern-history-v1')||[];const next=visits.filter(v=>v.id!==grove.id);next.unshift({id:grove.id,at:new Date().toLocaleDateString(),correct:grove.answers.filter(a=>a.correct).length,answered:grove.answers.length,hints:grove.hints,wrongTests:grove.wrongTests||0,wrongRepairs:grove.wrongRepairs||0});window.fixiverseStorage.setItem('fixiverse-pattern-history-v1',JSON.stringify(next.slice(0,30)));}window.fixiverseStorage.setItem(PKEY,JSON.stringify(grove));if(grove.repaired)window.fixiverseStorage.setItem('fixiverse-grove-repaired-v1','true');storage=!window.fixiverseStorage.memoryOnly;}catch{storage=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('[data-slot]'))return;grove=patternReduce(grove,{type:'block',index:+e.target.dataset.slot,value:e.target.value});persist();patternScreen();document.querySelector(`[data-slot="${e.target.dataset.slot}"]`)?.focus({preventScroll:true});});
document.addEventListener('click',e=>{const b=e.target.closest('[data-hub]');if(!b)return;const a=b.dataset.hub;if(a==='tutor'){location.hash='tutor';window.fixiverseTutor.show();return;}if(a==='text-size'){try{const p=read('fixiverse-access-v1')||{};p.large=!p.large;window.fixiverseStorage.setItem('fixiverse-access-v1',JSON.stringify(p));root.classList.toggle('large',p.large);b.setAttribute('aria-pressed',String(p.large));document.querySelector('#announcement').textContent=p.large?'Larger text on':'Larger text off';}catch{document.querySelector('#announcement').textContent='Text size could not be saved.';}return;}if(a==='home'){home();return;}if(a==='fraction'){document.title='Fixiverse · Fraction Foundry';window.fixiverseFraction.show();return;}if(a==='pattern'){patternScreen();return;}if(a==='voice'){if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(document.querySelector('main').innerText));}return;}if(a==='new-pattern'){grove=newPattern();persist();patternScreen();return;}try{grove=patternReduce(grove,{type:a,value:b.dataset.value});persist();patternScreen();document.querySelector('#announcement').textContent=grove.feedback;}catch(err){grove.feedback=err.message;patternScreen();document.querySelector('#announcement').textContent=err.message;}});
let groveTourSnapshot=null;window.fixiversePatternTour={scene:stage=>{if(groveTourSnapshot===null)groveTourSnapshot=structuredClone(grove);grove=window.fixiverseJourneyModels.patternJourney(stage);patternScreen();},end:()=>{if(groveTourSnapshot!==null){grove=groveTourSnapshot;groveTourSnapshot=null;}}};
window.fixiversePatternChecks=PATTERN_CHECKS;window.fixiverseLaunch=mission=>{if(mission==='fraction'){document.title='Fixiverse · Fraction Foundry';window.fixiverseFraction.show();}else patternScreen();};window.fixiverseHome=home;
if(['#lab-fraction','#lab-pattern'].includes(location.hash))window.fixiverseLab.show(location.hash.slice(5));else if(['#teach-fraction','#teach-pattern'].includes(location.hash))window.fixiverseMentor.show(location.hash.slice(7));else if(location.hash==='#session')window.fixiverseSession.show();else if(location.hash==='#tutor')window.fixiverseTutor.show();else home();
